'use strict';
/**
 * Bundles: topic plugins assembled from items that live elsewhere in the repo.
 *
 *   bundles/<name>.json  →  (agent-kit build)  →  plugins/<name>/   (generated, do not edit)
 *
 * The source items (skills/, agents/, ...) stay the single source of truth, so upstream sync
 * keeps working; `build --check` fails when a generated plugin drifts from its sources.
 */
const fs = require('fs');
const path = require('path');
const { repoRoot, exists, isDir, readJSON, listFiles, template, deepMap, rmrf, ensureDir } = require('./util');
const { select } = require('./catalog');
const mcp = require('./mcp');

const MARKER = '<!-- generated by agent-kit from bundles/';
const BUNDLE_TYPES = ['skill', 'agent', 'command', 'mcp', 'hook'];

function bundlesDir(root = repoRoot()) { return path.join(root, 'bundles'); }

function loadBundles(root = repoRoot()) {
  const dir = bundlesDir(root);
  if (!isDir(dir)) return [];
  return fs.readdirSync(dir).filter((f) => f.endsWith('.json')).sort().map((f) => {
    const file = path.join(dir, f);
    const spec = readJSON(file, {});
    return { name: spec.name || f.replace(/\.json$/, ''), fileName: f, file, spec };
  });
}

/** A plugin directory is "generated" when its README carries our marker. */
function isGenerated(pluginDir) {
  const readme = path.join(pluginDir, 'README.md');
  return exists(readme) && fs.readFileSync(readme, 'utf8').startsWith(MARKER);
}

function validateBundle(b, catalog) {
  const errors = [];
  const { spec } = b;
  if (!/^[a-z0-9][a-z0-9-]{0,63}$/.test(b.name)) errors.push('name must be kebab-case');
  if (spec.name && `${spec.name}.json` !== b.fileName) errors.push(`file must be named ${spec.name}.json`);
  if (!spec.description) errors.push('missing "description"');
  if (!Array.isArray(spec.include) || !spec.include.length) errors.push('"include" must be a non-empty list of type/name');
  const dir = path.join(repoRoot(), 'plugins', b.name);
  if (exists(dir) && !isGenerated(dir)) errors.push(`plugins/${b.name} exists and is hand-written — pick another bundle name`);
  for (const sel of spec.include || []) {
    try {
      for (const it of select(catalog, [sel])) {
        if (!BUNDLE_TYPES.includes(it.type)) errors.push(`${it.id}: ${it.type}s cannot go into a plugin`);
        if (it.type === 'hook' && !it.meta.claude) errors.push(`${it.id}: hook has no "claude" section`);
      }
    } catch (e) { errors.push(e.message); }
  }
  return errors.map((e) => `bundles/${b.fileName}: ${e}`);
}

/** Render one bundle into a Map(relative path → { data: Buffer, mode }). */
function renderBundle(b, catalog, pkg = {}) {
  const files = new Map();
  const put = (rel, data, mode = 0o644) => files.set(rel, { data: Buffer.isBuffer(data) ? data : Buffer.from(data), mode });
  const copy = (src, destRel) => {
    if (isDir(src)) {
      for (const f of listFiles(src)) {
        const p = path.join(src, f);
        put(`${destRel}/${f}`, fs.readFileSync(p), fs.statSync(p).mode & 0o111 ? 0o755 : 0o644);
      }
    } else put(destRel, fs.readFileSync(src));
  };

  const { spec } = b;
  const items = select(catalog, spec.include);
  const mcpServers = {};
  const hooks = {};

  for (const it of items) {
    switch (it.type) {
      case 'skill': copy(it.path, `skills/${it.name}`); break;
      case 'agent': copy(it.path, `agents/${it.name}.md`); break;
      case 'command': copy(it.path, `commands/${it.name}.md`); break;
      case 'mcp': {
        const local = it.file && isDir(it.path);
        if (local) copy(it.path, `mcp/${it.name}`);
        // keep ${HOME} for Claude Code to expand at runtime instead of baking in the build machine's path
        const vars = { HOME: '${HOME}', ITEM_DIR: '${CLAUDE_PLUGIN_ROOT}/mcp/' + it.name };
        mcpServers[it.name] = mcp.toClaudeCode(mcp.prepare(it.meta, 'claude-code', vars));
        break;
      }
      case 'hook': {
        copy(it.dir, `hooks/${it.name}`);
        const events = deepMap(it.meta.claude, (s) => template(s, { HOOK_DIR: '${CLAUDE_PLUGIN_ROOT}/hooks/' + it.name }));
        for (const [event, entries] of Object.entries(events)) hooks[event] = (hooks[event] || []).concat(entries);
        break;
      }
      default: throw new Error(`bundles/${b.fileName}: ${it.id} cannot be bundled`);
    }
  }
  if (Object.keys(mcpServers).length) put('.mcp.json', JSON.stringify({ mcpServers }, null, 2) + '\n');
  if (Object.keys(hooks).length) put('hooks/hooks.json', JSON.stringify({ hooks }, null, 2) + '\n');

  const manifest = {
    name: b.name,
    // No version by default: Claude Code then uses the git commit SHA, so upstream updates of the
    // bundled items always reach users. Set "version" in the bundle to pin/release manually.
    ...(spec.version ? { version: spec.version } : {}),
    description: spec.description,
    author: spec.author || pkg.author,
    ...(spec.license ? { license: spec.license } : {}),
    ...(spec.homepage ? { homepage: spec.homepage } : {}),
    ...(spec.keywords && spec.keywords.length ? { keywords: spec.keywords } : {}),
  };
  put('.claude-plugin/plugin.json', JSON.stringify(manifest, null, 2) + '\n');

  const rows = items.map((it) => {
    const origin = it.source ? `[${it.source.repo.replace(/^https:\/\/github\.com\//, '')}](${it.source.repo}/tree/${it.source.ref || 'HEAD'}/${it.source.path})${it.source.license ? ` · ${it.source.license}` : ''}` : 'original';
    return `| ${it.type} | \`${it.name}\` | ${(it.description || '').replace(/\s+/g, ' ').replace(/\|/g, '\\|')} | ${origin} |`;
  });
  put('README.md', [
    `${MARKER}${b.fileName} — do not edit; change the source items or the bundle, then run \`agent-kit build\` -->`,
    `# ${b.name}`,
    '',
    spec.description,
    '',
    '| 类型 | 名称 | 说明 | 来源 |',
    '| --- | --- | --- | --- |',
    ...rows,
    '',
    '## 安装',
    '',
    '```bash',
    'claude plugin marketplace add hidontknow/agent-kit',
    `claude plugin install ${b.name}@agent-kit`,
    '```',
    '',
  ].join('\n'));
  return files;
}

/**
 * Write (or, with check=true, only compare) every bundle's plugin directory.
 * Also removes generated plugin dirs whose bundle was deleted. Returns the list of stale paths.
 */
function syncBundles(catalog, { check = false, pkg = {} } = {}) {
  const root = repoRoot();
  const stale = [];
  const bundles = loadBundles(root);
  for (const b of bundles) {
    const dir = path.join(root, 'plugins', b.name);
    const want = renderBundle(b, catalog, pkg);
    const have = new Set(isDir(dir) ? listFiles(dir) : []);
    let dirty = have.size !== want.size;
    for (const [rel, f] of want) {
      const p = path.join(dir, rel);
      if (!have.has(rel) || !fs.readFileSync(p).equals(f.data) || ((fs.statSync(p).mode & 0o111) !== 0) !== ((f.mode & 0o111) !== 0)) { dirty = true; break; }
    }
    if (!dirty) continue;
    stale.push(`plugins/${b.name}/`);
    if (check) continue;
    rmrf(dir);
    for (const [rel, f] of want) {
      const p = path.join(dir, rel);
      ensureDir(path.dirname(p));
      fs.writeFileSync(p, f.data);
      fs.chmodSync(p, f.mode);
    }
  }
  const pluginsRoot = path.join(root, 'plugins');
  if (isDir(pluginsRoot)) {
    for (const n of fs.readdirSync(pluginsRoot)) {
      const dir = path.join(pluginsRoot, n);
      if (isGenerated(dir) && !bundles.some((b) => b.name === n)) {
        stale.push(`plugins/${n}/ (bundle removed)`);
        if (!check) rmrf(dir);
      }
    }
  }
  return stale;
}

module.exports = { loadBundles, validateBundle, renderBundle, syncBundles, isGenerated, MARKER };
